  "Greeting_FutureHope": {"ko":"장래희망","en":"Dream","ja":"将来の夢","zh":"未来梦想","vi":"Ước mơ","th":"ความฝันในอนาคต","ru":"Мечта","id":"Cita-cita"},
  "Greeting_FutureHopeContent": {"ko":"K-컬처와 로컬 전통을 결합해 새로운 관광·라이프스타일 콘텐츠를 만드는 크리에이터","en":"","ja":"","zh":""},
  "Greeting_Introdution": {"ko":"자기소개","en":"Intro","ja":"自己紹介","zh":"你好","vi":"Giới thiệu bản thân","th":"แนะนำตัว","ru":"О себе","id":"Profil Diri"},
  "Greeting_IntrodutionContent": {"ko":"저는 현재 제주도 홍보모델로 활동하고 있어요! K-콘텐츠와 제주 문화에 관심을 가지고, 제주를 방문하는 여행객들에게 유용한 정보와 특별한 경험을 전달하고 있어요. 제주 주요 관광 거점에서 여행 안내부터 지역 콘텐츠 소개까지, 제주 여행의 즐거움을 함께 만들어갑니다.","en":"","ja":"","zh":""},
  "Greeting_Hobby_First": {"ko":"K-POP","en":"K-POP","ja":"K-POP","zh":"K-POP","vi":"K-POP","th":"K-POP","ru":"K-POP","id":"K-POP"},
  "Greeting_Hobby_First_Desc_1": {"ko":"K-POP 댄스로 에너지를 충전해요!","en":"","ja":"","zh":""},
  "Greeting_Hobby_First_Desc_2": {"ko":"좋아하는 안무를 하나씩 배우며 즐거운 시간을 보내요.  신나는 음악이 들리면 어디서든 리듬을 타게 된답니다.","en":"","ja":"","zh":""},
  "Greeting_Hobby_Second": {"ko":"런닝","en":"","ja":"","zh":""},
  "Greeting_Hobby_Second_Desc_1": {"ko":"달리는 순간이 가장 행복해요!","en":"","ja":"","zh":""},
  "Greeting_Hobby_Second_Desc_2": {"ko":"상쾌한 바람을 맞으며 제주 곳곳을 달리는 시간을 사랑해요. 좋은 코스만 보이면 언제 어디서든 바로 러닝을 즐긴답니다.","en":"","ja":"","zh":""},
  "Greeting_Hobby_Third": {"ko":"테니스","en":"","ja":"","zh":""},
  "Greeting_Hobby_Third_Desc_1": {"ko":"테니스는 내 스트레스 해소법!","en":"Tennis is my way of relieving stress!","ja":"テニスは私のストレス解消法！","zh":"网球是我释放压力的方法！","vi":"Tennis là cách giải tỏa căng thẳng của mình!","th":"เทนนิสคือวิธีคลายเครียดของฉัน!","ru":"Теннис — мой способ снять стресс!","id":"Tenis adalah cara melepas stresku!"},
  "Greeting_Hobby_Third_Desc_2": {"ko":"랠리를 이어가며 한 점 한 점 승부를 즐기는 시간이 가장 행복해요. 친구들과 함께 경기를 하거나 새로운 기술을 연습하며 건강한 에너지를 충전한답니다.","en":"","ja":"","zh":""},
  "Greeting_Healthy_Habit_First": {"ko":"목·어깨","en":"","ja":"","zh":""},
  "Greeting_Healthy_Habit_First_Desc_1": {"ko":"여행의 설렘만큼 몸도 가볍게 풀어보세요.","en":"","ja":"","zh":""},
  "Greeting_Healthy_Habit_First_Desc_2": {"ko":"여행 중 쌓인 목과 어깨의 긴장을 가볍게 풀어보세요. 화면 속 동작을 천천히 따라 하며 몸을 리프레시하고, 더욱 편안한 여행을 이어가세요.","en":"","ja":"","zh":""},
  "Greeting_Healthy_Habit_Second": {"ko":"허리","en":"","ja":"","zh":""},
  "Greeting_Healthy_Habit_Second_Desc_1": {"ko":"비행과 여행으로 지친 몸, 잠시 쉬어가세요.","en":"","ja":"","zh":""},
  "Greeting_Healthy_Habit_Second_Desc_2": {"ko":"오랜 이동으로 뻐근해진 허리를 시원하게 풀어보세요. 간단한 스트레칭으로 몸의 균형을 되찾고, 가벼운 몸으로 여행을 시작해 보세요.","en":"","ja":"","zh":""},
  "Greeting_Healthy_Habit_Third": {"ko":"기분전환","en":"","ja":"","zh":""},
  "Greeting_Healthy_Habit_Third_Desc_1": {"ko":"잠시 멈춰, 기분 좋은 에너지를 채워보세요.","en":"","ja":"","zh":""},
  "Greeting_Healthy_Habit_Third_Desc_2": {"ko":"간단한 스트레칭을 따라 하며 긴장을 풀고, 여행 중 쌓인 피로를 자연스럽게 덜어보세요. 잠깐의 휴식이 제주 여행을 더욱 즐겁게 만드는 특별한 시간이 될 거예요.","en":"","ja":"","zh":""},
  "Help_Content": {"ko":"","en":"","ja":"","zh":""},
  "Photo_HanbokTry": {"ko":"AR 한복체험","en":"AR Hanbok Try-On","ja":"AR 韓服 体験","zh":"Ar 韩服 体验","vi":"Trải nghiệm Hanbok AR","th":"ลองชุดฮันบก AR","ru":"Примерка ханбока в AR","id":"Pengalaman Hanbok AR"},
  "Photo_HanbokSelect": {"ko":"한복/의상 선택하기","en":"Choose Hanbok","ja":"韓服を選ぶ","zh":"选择韩服","vi":"Chọn Hanbok/Trang phục","th":"เลือกชุดฮันบก/เครื่องแต่งกาย","ru":"Выбор ханбока/костюма","id":"Pilih Hanbok/Busana"},
  "Photo_HanbokSelectContent": {"ko":"원하시는 의상을 고르고 선택 완료 버튼을 누른뒤 사진촬영 버튼을 눌러주세요","en":"Please choose your desired costume and press the \"Complete Selection\" button","ja":"お好きな衣装を選んで「選択完了」ボタンを押してください","zh":"请选择您喜欢的服装，然后点击“完成选择”按钮","vi":"Chọn trang phục, nhấn 'Đã chọn xong' rồi nhấn 'Chụp ảnh'.","th":"เลือกชุดที่ชอบ กด 'เลือกเสร็จแล้ว' แล้วกด 'ถ่ายภาพ' ค่ะ","ru":"Выберите желаемый костюм, нажмите кнопку «Выбор завершен», а затем нажмите кнопку «Сделать фото».","id":"Pilih busana, tekan 'Selesai Memilih' lalu 'Ambil Foto'."},
  "Hanbok_1": {"ko":"여자 한복","en":"W>Hanbok","ja":"女性用韓服","zh":"女式韩服","vi":"Hanbok nữ","th":"ชุดฮันบกหญิง","ru":"Женский ханбок","id":"Hanbok Wanita"},
  "Hanbok_2": {"ko":"여자 모델","en":"M>Model","ja":"女性モデル","zh":"女性模特","vi":"Người mẫu nữ","th":"นางแบบ","ru":"Женская модель","id":"Model Wanita"},
  "Hanbok_3": {"ko":"남자 한복","en":"W>Hanbok","ja":"男性用韓服","zh":"男式韩服","vi":"Hanbok nam","th":"ชุดฮันบกชาย","ru":"Мужской ханбок","id":"Hanbok Pria"},
  "Hanbok_4": {"ko":"남자 모델","en":"M>Model","ja":"男性モデル","zh":"男性模特","vi":"Người mẫu nam","th":"นายแบบ","ru":"Мужская модель","id":"Model Pria"},
  "Hanbok_5": {"ko":"글로벌 의상","en":"World","ja":"世界の衣装","zh":"世界服饰","vi":"Trang phục quốc tế","th":"ชุดนานาชาติ","ru":"Мировые костюмы","id":"Busana Global"},
  "Hanbok_6": {"ko":"이벤트/취사병","en":"Events","ja":"イベント","zh":"活动","vi":"Sự kiện / Kỷ niệm","th":"อีเวนต์ / วันสำคัญ","ru":"Мероприятия / Военный повар","id":"Event / Peringatan"},
  "Hanbok_7": {"ko":"브랜드의상","en":"Brand","ja":"ブランド","zh":"品牌","vi":"Trang phục thương hiệu","th":"ชุดแบรนด์เนม","ru":"Брендовая одежда","id":"Busana Brand"},
