  "Event_MBTI_types": {"ko":"[외향적, 경험적, 이성적, 계획적, 내향적, 상상적, 감성적, 즉흥적]","en":"[Extroverted, Experiential, Rational, Planned, Introverted, Imaginative, Emotional, Spontaneous]","ja":"[外向的、経験的、理性的、計画的、内向的、想像的、感性的、即興的]","zh":"[外向、经验、理性、计划、内向、想象、感性、即兴]","vi":"[Hướng ngoại, Dựa trên kinh nghiệm, Lý trí, Có kế hoạch, Hướng nội, Giàu trí tưởng tượng, Cảm xúc, Ngẫu hứng]","th":"[Ekstrovert, Berdasarkan Pengalaman, Rasional, Terencana, Introvert, Imajinatif, Emosional, Spontan]","ru":"[เปิดเผย, ตามประสบการณ์, ใช้เหตุผล, มีแบบแผน, เก็บตัว, ใช้จินตนาการ, ใช้อารมณ์, ตามสัญชาตญาณ]","id":"[Экстравертный, Опирающийся на опыт, Рациональный, Планирующий, Интровертный, Обладающий воображением, Эмоциональный, Спонтанный]"},
